def check_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = perm[j] - perm[i]
            vec = (dc, dr)
            if vec in vectors:
                print(f"Duplicate vector: {vec} from ({i},{perm[i]}) to ({j},{perm[j]})")
                return False
            vectors.add(vec)
    print(f"All {len(vectors)} vectors distinct")
    return True

perm = [0, 1, 5, 3, 8, 7, 4, 6, 2]
print(check_costas(perm))
# Also print grid
for r in range(9):
    line = ""
    for c in range(9):
        if perm[c] == r:
            line += "X"
        else:
            line += "."
    print(line)
